"""Decode PUBLIC test matrices generated by the ESP32 QR encoder over USB.

Requires pyserial, numpy and opencv-python. Does not read live WiFi credentials
or prove camera readability of the physical LCD.
"""
import argparse,json,re,time
from pathlib import Path
import cv2,numpy as np,serial
p=argparse.ArgumentParser();p.add_argument('--port',default='COM4');args=p.parse_args()
s=serial.Serial(port=None,baudrate=115200,timeout=.3);s.dtr=False;s.rts=False;s.port=args.port;s.open()
raw=b''
try:
    s.reset_input_buffer();s.write(b'QRTEST\n');s.flush()
    start=time.monotonic()
    while time.monotonic()-start<8:
        raw+=s.read(8192)
        if b'QR_TEST_WEB_END' in raw:break
finally:s.close()
expected={'WIFI':'WIFI:T:WPA;S:MSR-NAS-DEMO;P:EXAMPLEONLY123456;;','WEB':'http://192.168.4.1/?pair=1#pair='+'0'*32}
folder=Path(__file__).resolve().parent.parent/'.build/qr-public-fixtures';folder.mkdir(parents=True,exist_ok=True)
for label,payload in expected.items():
    match=re.search(rb'QR_TEST_'+label.encode()+rb'_BEGIN\s+([01\r\n]+)QR_TEST_'+label.encode()+rb'_END',raw)
    assert match,'No public QR fixture received'
    rows=match[1].decode().split();assert len(rows)==37 and all(len(r)==37 for r in rows)
    bitmap=np.array([[0 if c=='1' else 255 for c in r] for r in rows],dtype=np.uint8)
    bitmap=np.pad(bitmap,4,constant_values=255);bitmap=np.repeat(np.repeat(bitmap,4,axis=0),4,axis=1)
    assert bitmap.shape==(180,180)
    decoded,_,_=cv2.QRCodeDetector().detectAndDecode(bitmap)
    assert decoded==payload,'QR fixture decoding mismatch'
    cv2.imwrite(str(folder/(label.lower()+'.png')),bitmap)
print(json.dumps({'public_fixture_qrs_decoded':2,'size_pixels':[180,180],'quiet_zone_modules':4,'actual_esp32_encoder':True,'live_credentials_read':False,'physical_lcd_camera_scan':'not tested by this script'}))
